function applyProfile(aptId, profileKey) {
  const apt = S.apts.find(a=>a.id===aptId); if(!apt) return;
  const prof = PROPERTY_PROFILES[profileKey]; if(!prof) return;
  // Re-clicking the already-active pill used to copy profile defaults again and
  // silently turn Business tax off on private/b2b apartments (and wipe other
  // Advanced deviations). Only apply flags when the profile actually changes.
  if (apt.profile === profileKey) return;
  apt.profile = profileKey;
  Object.entries(prof.flags).forEach(function(entry){ apt[entry[0]] = entry[1]; });
  save(); renderCfg();
}

